BEGIN TRANSACTION;
CREATE TABLE contracts (
            contract_id TEXT PRIMARY KEY,
            supplier_id TEXT NOT NULL,
            start_date TEXT,
            end_date TEXT,
            compliance_status TEXT, "contract_start_date" TEXT, "contract_end_date" TEXT, "contract_value" TEXT, "currency" TEXT, "status" TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        );
CREATE TABLE data_quality_exceptions (
            exception_id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_file TEXT,
            source_table TEXT,
            record_data TEXT,
            error_message TEXT
        );
CREATE TABLE delivery_events (
            event_id TEXT PRIMARY KEY,
            shipment_id TEXT NOT NULL,
            event_type TEXT,
            event_timestamp TEXT,
            location TEXT, "delivery_event_id" TEXT, "source" TEXT,
            FOREIGN KEY (shipment_id) REFERENCES shipments(shipment_id)
        );
CREATE TABLE inspections (
            inspection_id TEXT PRIMARY KEY,
            supplier_id TEXT NOT NULL,
            shipment_id TEXT,
            inspected_quantity INTEGER,
            accepted_quantity INTEGER,
            rejected_quantity INTEGER,
            inspection_date TEXT, "po_line_id" TEXT, "defect_category" TEXT, "status" TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id),
            FOREIGN KEY (shipment_id) REFERENCES shipments(shipment_id)
        );
CREATE TABLE invoices (
            invoice_id TEXT PRIMARY KEY,
            po_id TEXT NOT NULL,
            supplier_id TEXT NOT NULL,
            invoice_amount REAL,
            currency TEXT,
            status TEXT,
            invoice_date TEXT,
            FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id),
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        );
CREATE TABLE po_lines (
            po_line_id TEXT PRIMARY KEY,
            po_id TEXT NOT NULL,
            product_id TEXT,
            ordered_quantity INTEGER,
            unit_price REAL, "item_code" TEXT, "line_amount" TEXT,
            FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id)
        );
CREATE TABLE purchase_orders (
            po_id TEXT PRIMARY KEY,
            supplier_id TEXT NOT NULL,
            site_id TEXT,
            order_date TEXT,
            expected_delivery_date TEXT,
            total_amount REAL,
            currency TEXT,
            status TEXT, "contract_id" TEXT, "required_date" TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id),
            FOREIGN KEY (site_id) REFERENCES sites(site_id)
        );
CREATE TABLE risk_signals (
            risk_signal_id TEXT PRIMARY KEY,
            supplier_id TEXT NOT NULL,
            source TEXT,
            severity TEXT,
            observed_at TEXT,
            description TEXT, "site_id" TEXT, "risk_type" TEXT, "status" TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        );
CREATE TABLE shipment_lines (
            shipment_line_id TEXT PRIMARY KEY,
            shipment_id TEXT NOT NULL,
            po_line_id TEXT,
            shipped_quantity INTEGER,
            FOREIGN KEY (shipment_id) REFERENCES shipments(shipment_id),
            FOREIGN KEY (po_line_id) REFERENCES po_lines(po_line_id)
        );
CREATE TABLE shipments (
            shipment_id TEXT PRIMARY KEY,
            po_id TEXT,
            supplier_id TEXT,
            dispatch_date TEXT,
            expected_delivery_date TEXT,
            actual_delivery_date TEXT,
            status TEXT, "carrier_name" TEXT,
            FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id),
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        );
CREATE TABLE sites (
            site_id TEXT PRIMARY KEY,
            supplier_id TEXT NOT NULL,
            site_name TEXT,
            country TEXT, "city" TEXT, "effective_from" TEXT, "effective_to" TEXT, "status" TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        );
CREATE TABLE supplier_scores (
            score_id TEXT PRIMARY KEY,
            supplier_id TEXT NOT NULL,
            delivery_score REAL,
            quality_score REAL,
            cost_score REAL,
            capacity_score REAL,
            compliance_score REAL,
            disruption_score REAL,
            final_score REAL,
            rating TEXT, "data_coverage" TEXT,
            FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
        );
CREATE TABLE suppliers (
            supplier_id TEXT PRIMARY KEY,
            supplier_name TEXT,
            category TEXT,
            country TEXT,
            status TEXT
        , "registration_date" TEXT, "monthly_capacity_units" TEXT);
CREATE INDEX idx_sites_supplier
        ON sites(supplier_id);
CREATE INDEX idx_orders_supplier
        ON purchase_orders(supplier_id);
CREATE INDEX idx_shipments_po
        ON shipments(po_id);
CREATE INDEX idx_inspections_supplier
        ON inspections(supplier_id);
CREATE INDEX idx_risks_supplier
        ON risk_signals(supplier_id);
DELETE FROM "sqlite_sequence";
COMMIT;
